import{_ as e,o as d,c as a,a2 as o}from"./chunks/framework.XctAhZuT.js";const u=JSON.parse('{"title":"课型说明","description":"一节 Lesson 有「类型」和「模板」。类型决定这节课在课程树里扮演什么角色，模板决定内容怎么组织。","frontmatter":{"description":"一节 Lesson 有「类型」和「模板」。类型决定这节课在课程树里扮演什么角色，模板决定内容怎么组织。"},"headers":[],"relativePath":"guide/lesson-types.md","filePath":"guide/lesson-types.md","lastUpdated":1787830168000}'),r={name:"guide/lesson-types.md"};function i(c,t,l,s,n,h){return d(),a("div",null,[...t[0]||(t[0]=[o('<h1 id="课型说明" tabindex="-1">课型说明 <a class="header-anchor" href="#课型说明" aria-label="Permalink to &quot;课型说明&quot;">​</a></h1><p>一节 Lesson 有「类型」和「模板」。类型决定这节课在课程树里扮演什么角色，模板决定内容怎么组织。</p><p>编写 JSON 时的合同见 <a href="/docs/authoring/course-layout">课程目录约定</a>。更细的字段示例在应用仓库 <code>docs/authoring/lesson-type-templates.md</code>。</p><h2 id="六种课" tabindex="-1">六种课 <a class="header-anchor" href="#六种课" aria-label="Permalink to &quot;六种课&quot;">​</a></h2><table tabindex="0"><thead><tr><th>课型</th><th>模板</th><th>做什么</th></tr></thead><tbody><tr><td>新知课</td><td><code>intro</code></td><td>4 个子课时依次引入词汇、表达与语法，是每个主题的起点。</td></tr><tr><td>练习课</td><td><code>practice</code></td><td>用更高难度复练新知课内容，巩固而不是重复。</td></tr><tr><td>听力课</td><td><code>listening</code></td><td>先辨音，再理解，最后整体听懂一段。</td></tr><tr><td>阅读课</td><td><code>reading</code></td><td>一篇短文加理解题，把词汇和语法放进语境。</td></tr><tr><td>复习课</td><td><code>review</code></td><td>混合复习已学内容，由课程树按先修解锁。</td></tr><tr><td>挑战课</td><td><code>mastery</code></td><td>单次掌握度检验，通过才能继续往后。</td></tr></tbody></table><p>对应到 JSON 里的 <code>type</code>：<code>normal</code>（intro / practice）、<code>listening</code>、<code>reading</code>、<code>review</code>、<code>challenge</code>。</p><h2 id="怎么选" tabindex="-1">怎么选 <a class="header-anchor" href="#怎么选" aria-label="Permalink to &quot;怎么选&quot;">​</a></h2><ul><li>第一次出现的词和句 → 新知课。</li><li>同一批材料加难再练 → 练习课。</li><li>需要听音或读短文 → 听力课 / 阅读课。</li><li>Unit 或 Section 收尾 → 复习课，必要时加挑战课。</li></ul><p>教师在编辑器里选模板后，会生成默认结构（子课、阶段），再往里填词和题目即可。</p><h2 id="下一步" tabindex="-1">下一步 <a class="header-anchor" href="#下一步" aria-label="Permalink to &quot;下一步&quot;">​</a></h2><ul><li><a href="/docs/authoring/teacher-guide">教师指南</a></li><li><a href="/docs/guide/curriculum">课程结构</a></li></ul>',11)])])}const _=e(r,[["render",i]]);export{u as __pageData,_ as default};
